item.aggregated_output:
        with _backend_stdout_to_stderr():
            self._verify_session_pack_source(session, target, pack, pdsc_device)
            getattr(session, "open")()
            self._verify_session_pack_source(session, target, pack, pdsc_device)

    @staticmethod
    def _verify_session_pack_source(
        session: object,
        target: str | None,
        pack: CmsisPack | None,
        pdsc_device: str | None = None,
    ) -> None:
        """Prove the instantiated target came from the selected pack object."""

        if pack is None:
            return
        session_target = getattr(session, "target", None)
        source = getattr(type(session_target), "_pack_device", None)
        if source is None or not any(source is device for device in pack.devices):
            raise TargetConnectionError(
                f"pyOCD target {target!r} was already registered by a different device pack; "
                "restart with one unambiguous pinned provider."
            )
        if pdsc_device is not None and source.part_number.casefold() != pdsc_device.casefold():
            raise TargetConnectionError(
                f"pyOCD target {target!r} did not instantiate the persisted PDSC device."
            )

    def open(
        self,
        *,
        board: BoardConfig | None,
        unique_id: str | None,
        target: str | None,
        server_timeouts: ServerTimeoutConfig | None = None,
        protocol: str | None = None,
        connect_mode: str | None = None,
        pack_path: Path | None = None,
        pack_sha256: str | None = None,
        pdsc_device: str | None = None,
        frequency_hz: int | None = None,
        operation_timeout_seconds: float | None = None,
    ) -> TargetSessionHandle:
        del operation_timeout_seconds
        # Reset-connect is action/profile-bound. Unlike ordinary open(), it
        # must not inherit ambient launch overrides when an input is omitted.
        probe_uid = unique_id
        target_override = target or (board.pyocd_target if board else None)
        options = build_session_options(board, target_override, server_timeouts)
        if protocol is not None:
            if protocol not in {"default", "swd", "jtag"}:
                raise ValueError(f"Unsupported pyOCD debug protocol: {protocol}")
            options = dict(options or {})
            options["dap_protocol"] = protocol
        if connect_mode is not None:
            if connect_mode not in {"attach", "halt", "pre-reset", "under-reset"}:
                raise ValueError(f"Unsupported pyOCD connect mode: {connect_mode}")
            options = dict(options or {})
            options["connect_mode"] = connect_mode
        if frequency_hz is not None:
            if isinstance(frequency_hz, bool) or frequency_hz <= 0:
                raise ValueError("frequency_hz must be a positive integer")
            options = dict(options or {})
            options["frequency"] = frequency_hz
        # Give pyOCD only the manifest-selected pack for this exact target. Passing
        # every local pack lets an unrelated provider win target resolution.
        if pack_path is not None:
            if pack_sha256 is None:
                raise ValueError("pack_sha256 is required with a quarantined pack_path")
            pack_object = _quarantined_cmsis_pack(pack_path.expanduser().resolve(), pack_sha256)
        elif pack_sha256 is not None:
            raise ValueError("pack_sha256 is valid only with a quarantined pack_path")
        else:
            selected_pack = (
                verified_pack_for_target(target_override) if target_override is not None else None
            )
            pack_object = _cmsis_pack_for(selected_pack) if selected_pack is not None else None
        if pack_object is not None:
            options = dict(options or {})
            options["pack"] = [pack_object]
        with _pack_target_scope(pack_object, target_override, pdsc_device):
            session = self._choose_session(probe_uid=probe_uid, options=options)
        if session is None:
            raise ProbeNotFoundError("No matching debug probe found.")
        try:
            self._open_and_verify_session(
                session, board, target_override, pack_object, pdsc_device
            )
        except Exception as exc:  # noqa: BLE001 - preserve backend context
            try:
                _close_session(session)
            except Exception:
                pass
            if not _should_retry_without_uid(board, probe_uid, exc):
                raise _typed_backend_error(exc) from exc
            with _pack_target_scope(pack_object, target_override, pdsc_device):
                retry_session = self._choose_session(probe_uid=None, options=options)
            if retry_session is None:
                raise ProbeNotFoundError("No matching debug probe found.") from exc
            retry_uid = getattr(getattr(retry_session, "probe", None), "unique_id", None)
            if not _same_probe_uid(probe_uid, retry_uid):
                try:
                    _close_session(retry_session)
                except Exception:
                    pass
        raise RuntimeError(
            f"Build directory must be new or empty; preserve existing contents: {build_dir}"
        )
    return project_dir, build_dir


def _validate_resolved_build_root(
    project_dir: Path, build_root: Path, *, require_fresh_build: bool
) -> None:
    """Validate the captured output-root identity without rejecting a stable link."""

    if build_root == Path(build_root.anchor):
        raise RuntimeError("Build directory must be a dedicated non-root directory.")
    if require_fresh_build and build_root == Path.home().resolve():
        raise RuntimeError("Build directory must be a dedicated non-root, non-home directory.")
    if require_fresh_build and (
        project_dir == build_root or project_dir.is_relative_to(build_root)
    ):
        raise RuntimeError("Build directory must not equal or contain the project directory.")


def _artifact_paths(
    build_dir: Path,
    *,
    expected_root: Path | None = None,
) -> DiscoveredArtifacts:
    root = expected_root or build_dir.resolve(strict=True)
    if build_dir.resolve(strict=True) != root:
        raise RuntimeError("Artifact search root was replaced or redirected during the build.")
    files = tuple(
        path
        for path in build_dir.rglob("*")
        if path.is_file() and path.resolve().is_relative_to(root)
    )
    elves = tuple(sorted((path.resolve() for path in files if _is_loadable_elf(path)), key=str))
    maps = tuple(sorted((
        path.resolve()
        for path in files
        if path.suffix.casefold() == ".map" and path.stat().st_size > 0 and not _has_elf_magic(path)
    ), key=str))
    if not elves or not maps:
        raise RuntimeError(
            "Native build succeeded without a discoverable loadable ELF and nonempty linker map. "
            "Declare outputs with --artifact-elf and --artifact-map."
        )
    ambiguous = len(elves) > 1 or len(maps) > 1
    elf = next(iter(elves), None) if not ambiguous else None
    hexes = tuple(
        path.resolve()
        for path in files
        if elf is not None and path.suffix.casefold() == ".hex" and path.stem == elf.stem
    )
    if len(hexes) > 1:
        raise RuntimeError(
            "Native build produced multiple same-stem HEX artifacts; pass --artifact-hex."
        )
    return {
        "elf": str(elf) if elf is not None else None,
        "hex": str(next(iter(hexes), None)) if hexes else None,
        # A selected ELF/MAP pair is one atomic flash-planning fact. Do not
        # retain the singleton side when the other required role is ambiguous.
        "map": str(next(iter(maps), None)) if not ambiguous else None,
        "elf_candidates": [str(path) for path in elves] if len(elves) > 1 else [],
        "map_candidates": [str(path) for path in maps] if len(maps) > 1 else [],
        "artifact_selection": (
        raise RuntimeError(
            "No build command was supplied. Inspect the project's build files and pass its exact "
            "native argv after '--'. The server does not select a build system, SDK, compiler, "
            "or target."
        )
    project_dir, build_dir = _validate_paths(
        args.project_dir,
        args.build_dir,
        require_fresh_build=False,
    )
    declared_artifacts = _declared_artifacts(args)
    for value in declared_artifacts.values() if declared_artifacts else ():
        if value is not None:
            _artifact_candidate(build_dir, value)

    offline = bool(getattr(args, "offline", False))
    timeout_seconds = _timeout_seconds(getattr(args, "timeout_seconds", BUILD_TIMEOUT_SECONDS))
    overrides = _environment_overrides(getattr(args, "env", ()) or ())
    argv = command
    cwd = _resolve_cwd(getattr(args, "cwd", None), default=project_dir)
    child_environment = _apply_environment_overrides(os.environ, overrides)
    if offline:
        child_environment = _offline_environment(child_environment)

    build_dir.mkdir(parents=True, exist_ok=True)
    created_build_root = build_dir.resolve(strict=True)
    _validate_resolved_build_root(
        project_dir,
        created_build_root,
        require_fresh_build=False,
    )
    evidence: dict[str, object] = {
        "schema_version": 2,
        "cwd": str(cwd),
        "argv": argv,
        "exit_code": None,
        "artifacts": {"elf": None, "hex": None, "map": None},
        "artifact_assurance": None,
        "network_policy": "best_effort_offline_guards" if offline else "inherited",
        "offline_guards": offline,
        "environment_overrides": sorted(overrides),
        "timeout_seconds": timeout_seconds,
        "helper_provisioning": False,
    }
    try:
        completed = run_owned(
            argv,
            cwd=cwd,
            env=child_environment,
            check=False,
            timeout=timeout_seconds,
        )
    except subprocess.TimeoutExpired as exc:
        message = (
            f"Build command exceeded the {timeout_seconds:g}-second timeout; "
            "inspect its output, then retry with a build command that terminates."
        )
        evidence["process_error"] = message
        raise BuildEvidenceError(message, evidence) from exc
    except OSError as exc:
        message = (
            f"Cannot start build executable {argv[0]!r}; verify the exact argv, cwd, PATH, "
            "and --env overrides."
        )
        evidence["process_error"] = message
        raise BuildEvidenceError(message, evidence) from exc
    except RuntimeError as exc:
        message = f"Build process ownership failed: {exc}"
        evidence["process_error"] = message
        raise BuildEvidenceError(message, evidence) from exc
    evidence["exit_code"] = completed.returncode
    try:
        try:
            root_changed = build_dir.resolve(strict=True) != created_build_root
        except OSError as exc:
            raise RuntimeError(
                "Artifact search root disappeared or became inaccessible during the build."
            ) from exc
        if root_changed:
            raise RuntimeError("Artifact search root was replaced or redirected during the build.")
        selected_artifacts: dict[str, str | None]
        metadata: dict[str, object]
        if completed.returncode != 0:
            selected_artifacts = {"elf": None, "hex": None, "map": None}
            metadata = {}
        elif declared_artifacts is not None:
            selected_artifacts = _validate_declared_artifacts(
                build_dir, declared_artifacts, expected_root=created_build_root
            )
            metadata = {}
        else:
            discovered = _artifact_paths(build_dir, expected_root=created_build_root)
            selected_artifacts = {
                role: discovered[role] for role in ("elf", "hex", "map")
            }
            metadata = {
                role: discovered[role]
                for role in (
                    "elf_candidates",
                    "map_candidates",
                    "artifact_selection",
                    "artifact_selection_remedy",
                )
            }
        if completed.returncode == 0 and not any(
            selected_artifacts.values()
        ) and not any(metadata.get(role) for role in ("elf_candidates", "map_candidates")):
            raise RuntimeError(
                "Native build succeeded without a declared or discoverable output. Declare any "
                "project-native output with --artifact ROLE=PATH."
            )
        assurance = (
            _artifact_assurance(
                selected_artifacts,
                declared=declared_artifacts is not None,
            )
            if completed.returncode == 0
            else None
        )
    except RuntimeError as exc:
        evidence["artifact_validation_error"] = str(exc)
        raise BuildEvidenceError(str(exc), evidence) from exc
    evidence["artifacts"] = {**selected_artifacts, **metadata}
    evidence["artifact_assurance"] = assurance
    print(json.dumps(evidence, sort_keys=True))
    return completed.returncode


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description=(
            "Run one firmware build as an owned process. Supply the project's exact native argv "
            "after '--'; the server does not select a build system or toolchain."
        )
    )
